.eclor-matrix-root {
  --em-fg: #091612;
  --em-bg: transparent;
  --em-accent: #1ef5b1;
  --em-grid: #e5e7e6;
  --em-header-bg: rgba(9, 22, 18, 0.1);
  --em-total-bg: #efefef;
  --em-band-bg: #f5f6f5;
  --em-hover-bg: color-mix(in srgb, var(--em-accent) 14%, transparent);
  --em-selected-bg: color-mix(in srgb, var(--em-accent) 28%, transparent);
  --em-focus: #091612;
  --em-good: #1ef5b1;
  --em-bad: #ff4d6d;
  --em-py: #8a9994;
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: Arial, "Segoe UI", wf_segoe-ui_normal, helvetica, sans-serif;
  color: var(--em-fg);
  background: var(--em-bg);
}
.em-scroll {
  width: 100%;
  height: 100%;
  overflow: auto;
}
.em-table {
  border-collapse: collapse;
  width: max-content;
  min-width: 100%;
}
.em-table th,
.em-table td {
  border: none;
  border-bottom: var(--em-grid-w, 1px) solid var(--em-hgrid-c, var(--em-grid));
  padding: var(--em-pad-y, 4px) var(--em-pad-x, 8px);
  text-align: right;
  white-space: nowrap;
}
.em-table thead th {
  position: sticky;
  top: 0;
  z-index: 2;
  background-color: #ffffff;
  background-image: linear-gradient(var(--em-header-bg), var(--em-header-bg));
  font-weight: 700;
  text-align: center;
  border-bottom: 1px solid var(--em-fg);
}
.em-table th.em-rowheader {
  position: sticky;
  left: 0;
  z-index: 1;
  background-color: var(--em-rowh-bg, #ffffff);
  text-align: left;
  font-weight: 400;
}
.em-table thead th.em-corner {
  z-index: 3;
  left: 0;
}
.em-table tr.em-subtotal {
  font-weight: 700;
}
.em-table tr.em-subtotal td,
.em-table tr.em-subtotal th.em-rowheader {
  background-color: var(--em-total-bg);
  color: var(--em-total-fg, inherit);
}
.em-table tbody tr:nth-child(even):not(.em-subtotal) td,
.em-table tbody tr:nth-child(even):not(.em-subtotal) th.em-rowheader {
  background-color: var(--em-band-bg);
}
.em-table tbody tr:hover:not(.em-subtotal) td,
.em-table tbody tr:hover:not(.em-subtotal) th.em-rowheader {
  background-color: var(--em-hover-bg);
}
.em-table tbody tr.em-selected td,
.em-table tbody tr.em-selected th.em-rowheader {
  background-color: var(--em-selected-bg) !important;
}
.em-table tbody tr:focus-visible {
  outline: none;
}
.em-table tbody tr:focus-visible th.em-rowheader {
  box-shadow: inset 0 0 0 2px var(--em-focus);
}
.em-chevron {
  display: inline-block;
  width: 14px;
  margin-right: 4px;
  cursor: pointer;
  user-select: none;
  color: var(--em-fg);
}
.em-density-compact {
  --em-pad-y: 1px;
}
.em-density-comfortable {
  --em-pad-y: 8px;
}
.em-nohgrid .em-table tbody td,
.em-nohgrid .em-table tbody th.em-rowheader {
  border-bottom-color: transparent;
}
.em-vgrid .em-table th,
.em-vgrid .em-table td {
  border-left: var(--em-vgrid-w, 1px) solid var(--em-vgrid-c, var(--em-grid));
}
.em-vgrid .em-table th.em-rowheader,
.em-vgrid .em-table th.em-corner {
  border-left: none;
}
.em-outer .em-table {
  border: var(--em-outer-w, 1px) solid var(--em-outer-c, var(--em-fg));
}
.em-noheadrule .em-table thead th {
  border-bottom-color: transparent;
}
.em-nochev .em-chevron {
  display: none;
}
.em-stnobold .em-table tr.em-subtotal {
  font-weight: 400;
}
.em-groupbold .em-table tbody tr.em-grouprow th.em-rowheader {
  font-weight: 700;
}
.em-nobands .em-table tbody tr:nth-child(even):not(.em-subtotal) td,
.em-nobands .em-table tbody tr:nth-child(even):not(.em-subtotal) th.em-rowheader {
  background-color: transparent;
}
.em-nobands .em-table tbody tr:nth-child(even):not(.em-subtotal) th.em-rowheader {
  background-color: var(--em-rowh-bg, #ffffff);
}
.em-groupbg .em-table tbody tr.em-grouprow td,
.em-groupbg .em-table tbody tr.em-grouprow th.em-rowheader {
  background-color: var(--em-group-bg);
}
.em-nobands .em-table tbody tr:hover:not(.em-subtotal) td,
.em-nobands .em-table tbody tr:hover:not(.em-subtotal) th.em-rowheader {
  background-color: var(--em-hover-bg);
}
.em-nobands.em-groupbg .em-table tbody tr.em-grouprow td,
.em-nobands.em-groupbg .em-table tbody tr.em-grouprow th.em-rowheader {
  background-color: var(--em-group-bg);
}
.em-hsep .em-table thead th {
  border-left: var(--em-hsep-w, 1px) solid var(--em-hsep-c, var(--em-grid));
}
.em-hsep .em-table thead th.em-corner {
  border-left: none;
}
.em-htop .em-table thead tr:first-child th {
  border-top: var(--em-htop-w, 1px) solid var(--em-htop-c, var(--em-fg));
}
.em-hwrap .em-table thead th {
  white-space: normal;
}
.em-rwrap .em-table tbody th.em-rowheader {
  white-space: normal;
}
.em-rlabelclamp {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: var(--em-rwrap-lines, 2);
  overflow: hidden;
}
.em-table.em-fixed {
  table-layout: fixed;
  min-width: 0;
}
.em-table.em-fixed th,
.em-table.em-fixed td {
  overflow: hidden;
  text-overflow: ellipsis;
}
.em-colgrip {
  position: absolute;
  top: 0;
  bottom: 0;
  right: -4px;
  width: 9px;
  cursor: col-resize;
  z-index: 5;
}
.em-colgrip:hover {
  background: var(--em-selected-bg);
}
.eclor-matrix-root .em-table thead th.em-gapcol {
  background-color: transparent;
  background-image: none;
  border-bottom-color: transparent;
  border-left: none;
}
.eclor-matrix-root .em-table tbody td.em-gapcol {
  background-color: transparent !important;
  border-bottom-color: transparent;
  border-left: none;
}
.eclor-matrix-root .em-table tbody tr.em-blankrow td {
  background-color: transparent;
  border-bottom-color: transparent;
}
.eclor-matrix-root .em-table tbody tr.em-blankrow th.em-rowheader {
  border-bottom-color: transparent;
}
.em-cmark {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--em-cmark, var(--em-accent));
  margin-left: 6px;
  vertical-align: 1px;
}
.em-table td.em-commentcell {
  text-align: left;
}
.em-commentclamp {
  max-width: 280px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.em-table thead th.em-commentth {
  vertical-align: middle;
}
.em-table th.ibcs-ac .em-hlabel {
  border-bottom: 3px solid var(--em-fg);
  padding-bottom: 1px;
}
.em-table th.ibcs-py {
  color: var(--em-py);
}
.em-table th.ibcs-bu .em-hlabel {
  border: 1px solid var(--em-fg);
  padding: 0 4px;
}
.em-table th.ibcs-fc .em-hlabel {
  border: 1px solid var(--em-fg);
  padding: 0 4px;
  background: repeating-linear-gradient(45deg, transparent 0 3px, rgba(9, 22, 18, 0.22) 3px 4px);
}
.em-table td.ibcs-py {
  color: var(--em-py);
}
.em-table td.ibcs-fc {
  background: repeating-linear-gradient(45deg, transparent 0 4px, rgba(9, 22, 18, 0.07) 4px 6px);
}
.em-barflex {
  display: flex;
  align-items: center;
  gap: 4px;
}
.em-barwrap {
  position: relative;
  flex: 1;
  min-width: 56px;
  height: 12px;
}
.em-barwrap::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--em-grid);
}
.em-bar {
  position: absolute;
  top: 1px;
  bottom: 1px;
}
.em-bar-pos {
  left: 50%;
  background: var(--em-good);
}
.em-bar-neg {
  right: 50%;
  background: var(--em-bad);
}
.em-bar-wf {
  left: auto;
  right: auto;
}
.em-bar-wf-pos {
  background: var(--em-good);
}
.em-bar-wf-neg {
  background: var(--em-bad);
}
.em-pinline {
  position: absolute;
  top: 50%;
  height: 2px;
  margin-top: -1px;
}
.em-pindot {
  position: absolute;
  top: 50%;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  transform: translate(-50%, -50%);
}
.em-pin-pos .em-pinline,
.em-pin-pos .em-pindot {
  background: var(--em-good);
}
.em-pin-neg .em-pinline,
.em-pin-neg .em-pindot {
  background: var(--em-bad);
}
.em-barlabel {
  white-space: nowrap;
}
.em-table.em-rot90 thead th .em-hlabel {
  display: inline-block;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  max-height: 140px;
}
.em-table.em-rot45 thead th {
  height: 64px;
  vertical-align: bottom;
  overflow: visible;
}
.em-table.em-rot45 thead th .em-hlabel {
  display: inline-block;
  transform: rotate(-45deg);
  transform-origin: left bottom;
  white-space: nowrap;
}
.em-table tbody tr.em-customrow th.em-rowheader {
  font-style: italic;
}
.em-table tbody tr.em-customrow td,
.em-table tbody tr.em-customrow th.em-rowheader {
  border-top: 1px dashed var(--em-fg);
}
.em-toolbar {
  position: absolute;
  top: 4px;
  right: 4px;
  z-index: 6;
  display: flex;
  gap: 4px;
}
.em-toolbar.em-toolbar-corner {
  position: static;
  display: inline-flex;
  vertical-align: middle;
}
.em-toolbtn {
  width: 24px;
  height: 24px;
  border: 1px solid var(--em-grid);
  border-radius: 4px;
  background: #ffffff;
  color: var(--em-fg);
  cursor: pointer;
  font-size: 13px;
  line-height: 1;
}
.em-toolbtn:hover {
  background: var(--em-hover-bg);
}
.em-editpanel,
.em-commentspanel {
  position: absolute;
  top: 32px;
  right: 4px;
  z-index: 7;
  width: 280px;
  max-height: calc(100% - 40px);
  overflow-y: auto;
  background: #ffffff;
  border: 1px solid var(--em-grid);
  border-radius: 6px;
  box-shadow: 0 4px 16px rgba(9, 22, 18, 0.18);
  padding: 8px;
  font-size: 11px;
  color: var(--em-fg);
}
.em-editpanel .em-paneltitle,
.em-commentspanel .em-paneltitle {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 700;
  margin-bottom: 6px;
}
.em-editpanel .em-panelclose,
.em-commentspanel .em-panelclose {
  border: none;
  background: none;
  cursor: pointer;
  font-size: 12px;
  color: var(--em-fg);
}
.em-editpanel .em-defitem,
.em-commentspanel .em-defitem {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 0;
  border-bottom: 1px solid var(--em-grid);
}
.em-editpanel .em-defitem .em-defkind,
.em-commentspanel .em-defitem .em-defkind {
  width: 16px;
  text-align: center;
  font-weight: 700;
  color: var(--em-py);
}
.em-editpanel .em-defitem .em-defname,
.em-commentspanel .em-defitem .em-defname {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.em-editpanel .em-defitem button,
.em-commentspanel .em-defitem button {
  border: none;
  background: none;
  cursor: pointer;
}
.em-editpanel .em-panelsection,
.em-commentspanel .em-panelsection {
  margin-top: 8px;
  padding-top: 6px;
  border-top: 1px solid var(--em-grid);
}
.em-editpanel .em-field,
.em-commentspanel .em-field {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 4px;
}
.em-editpanel .em-field label,
.em-commentspanel .em-field label {
  width: 14px;
  text-align: center;
  font-weight: 700;
  color: var(--em-py);
}
.em-editpanel .em-field input,
.em-commentspanel .em-field input,
.em-editpanel .em-field select,
.em-commentspanel .em-field select {
  flex: 1;
  font-size: 11px;
  padding: 3px 6px;
  border: 1px solid var(--em-grid);
  border-radius: 3px;
  font-family: inherit;
}
.em-editpanel .em-field input.em-invalid,
.em-commentspanel .em-field input.em-invalid {
  border-color: var(--em-bad);
}
.em-editpanel .em-panelsection > button,
.em-commentspanel .em-panelsection > button {
  width: 100%;
  margin-top: 2px;
  padding: 4px 6px;
  border: 1px solid var(--em-fg);
  border-radius: 4px;
  background: #ffffff;
  color: var(--em-fg);
  cursor: pointer;
  font-size: 11px;
}
.em-editpanel .em-panelsection > button:hover,
.em-commentspanel .em-panelsection > button:hover {
  background: var(--em-hover-bg);
}
.em-editpanel .em-panelhint,
.em-commentspanel .em-panelhint {
  margin-top: 8px;
  color: var(--em-py);
  font-size: 10px;
}
.em-editpanel .em-citem,
.em-commentspanel .em-citem {
  padding: 5px 0;
  border-bottom: 1px solid var(--em-grid);
}
.em-editpanel .em-crow,
.em-commentspanel .em-crow {
  font-weight: 700;
  margin-bottom: 2px;
}
.em-editpanel .em-cpath,
.em-commentspanel .em-cpath {
  color: var(--em-py);
  font-size: 10px;
  margin-left: 6px;
}
.em-editpanel .em-ctext,
.em-commentspanel .em-ctext {
  line-height: 1.4;
}
.em-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  color: #5e5e5e;
  font-size: 12px;
  text-align: center;
  padding: 8px;
  box-sizing: border-box;
}
.eclor-matrix-root.em-hc .em-table th,
.eclor-matrix-root.em-hc .em-table td,
.eclor-matrix-root.em-hc .em-table th.em-rowheader,
.eclor-matrix-root.em-hc .em-table thead th,
.eclor-matrix-root.em-hc .em-table tr.em-subtotal td,
.eclor-matrix-root.em-hc .em-table tr.em-subtotal th.em-rowheader,
.eclor-matrix-root.em-hc .em-table tbody tr:nth-child(even):not(.em-subtotal) td,
.eclor-matrix-root.em-hc .em-table tbody tr:nth-child(even):not(.em-subtotal) th.em-rowheader {
  background-color: var(--em-bg) !important;
  color: var(--em-fg) !important;
  border-color: var(--em-fg) !important;
}
.eclor-matrix-root.em-hc .em-table tbody tr.em-selected td,
.eclor-matrix-root.em-hc .em-table tbody tr.em-selected th.em-rowheader {
  color: var(--em-accent) !important;
}
.eclor-matrix-root.em-hc .em-table tbody tr:focus-visible th.em-rowheader {
  box-shadow: inset 0 0 0 2px var(--em-accent);
}
.eclor-matrix-root.em-hc .em-empty {
  color: var(--em-fg);
}
.eclor-matrix-root.em-hc .em-cmark {
  background: var(--em-fg) !important;
}
.eclor-matrix-root.em-hc .em-table thead th {
  background-image: none !important;
}
.eclor-matrix-root.em-hc .em-editpanel,
.eclor-matrix-root.em-hc .em-commentspanel,
.eclor-matrix-root.em-hc .em-toolbtn,
.eclor-matrix-root.em-hc .em-panelsection > button {
  background: var(--em-bg) !important;
  color: var(--em-fg) !important;
  border-color: var(--em-fg) !important;
}
.eclor-matrix-root.em-hc.em-nohgrid .em-table tbody td,
.eclor-matrix-root.em-hc.em-nohgrid .em-table tbody th.em-rowheader {
  border-bottom-color: transparent !important;
}
.eclor-matrix-root.em-hc.em-noheadrule .em-table thead th {
  border-bottom-color: transparent !important;
}
.eclor-matrix-root.em-hc .em-table thead th.em-gapcol,
.eclor-matrix-root.em-hc .em-table tbody td.em-gapcol,
.eclor-matrix-root.em-hc .em-table tbody tr.em-blankrow td,
.eclor-matrix-root.em-hc .em-table tbody tr.em-blankrow th.em-rowheader {
  border-bottom-color: transparent !important;
  border-left: none !important;
}
